package io.formkiln.server.storage;

import java.io.IOException;
import java.io.InputStream;

/** Stores uploaded files. Keys are opaque, generated by the server and never derived from user input. */
public interface ObjectStorage {

    void put(String key, InputStream content, long length, String contentType) throws IOException;

    InputStream get(String key) throws IOException;

    void delete(String key) throws IOException;
}
